<main class="container py-4 py-md-5"><div class="page-toolbar mb-3"><a href="<?= site_url('roles') ?>" class="back-button"><i class="fa-solid fa-arrow-left"></i><span>Kembali</span></a></div><section class="menu-shell monitoring-shell"><div class="menu-heading"><h1><?= $mode === 'create' ? 'Tambah Role' : 'Edit Role' ?></h1></div><?php $this->load->view('template/flash'); ?><form method="post" action="<?= $action ?>" class="mt-3"><div class="row g-3"><div class="col-md-6"><label class="form-label">Nama Role</label><input name="name" class="form-control" value="<?= html_escape($role['name']) ?>" required></div><div class="col-md-6"><label class="form-label">Status</label><select name="is_active" class="form-select"><option value="1" <?= !empty($role['is_active']) ? 'selected' : '' ?>>Aktif</option><option value="0" <?= empty($role['is_active']) ? 'selected' : '' ?>>Nonaktif</option></select></div><div class="col-12"><label class="form-label">Deskripsi</label><textarea name="description" class="form-control"><?= html_escape($role['description']) ?></textarea></div><div class="col-12"><label class="form-label d-block">Hak Akses</label><div class="row g-2"><?php foreach ($feature_options as $key => $label): ?><div class="col-md-4"><label class="form-check border rounded p-3"><input class="form-check-input ms-0 me-2" type="checkbox" name="permissions[]" value="<?= html_escape($key) ?>" <?= in_array($key, $permissions, true) ? 'checked' : '' ?>><?= html_escape($label) ?></label></div><?php endforeach; ?></div></div></div><button class="back-button border-0 mt-3" type="submit"><i class="fa-solid fa-save"></i><span>Simpan</span></button></form></section></main>
